<?php
class med_cisz_context { private ?object $settings; private object $patient; private object $organization; private object $practitioner; public function __construct( ?object $settings, object $patient, object $organization, object $practitioner ) { $this->settings = $settings; $this->patient = $patient; $this->organization = $organization; $this->practitioner = $practitioner; } public function getPatient(): object { return $this->patient; } public function getPatientResource(): ?object { $patient = $this->getPatient(); return $patient->profile ?? null; } public function getOrganization(): object { return $this->organization; } public function getPractitioner(): object { return $this->practitioner; } public function getSettings(): object { return $this->settings; } }